import { Contract, GlobalState, LocalState, BoxMap, Box, abimethod, baremethod, uint64, bytes, Txn, Global, Uint64, Bytes, assert, Account, itxn, gtxn, clone } from '@algorandfoundation/algorand-typescript'

export class JokePayPerCall extends Contract {
  owner = GlobalState<Account>({ key: 'o' })
  totalCalls = GlobalState<uint64>({ key: 'tc' })
  totalEarned = GlobalState<uint64>({ key: 'te' })
  pricePerCall = GlobalState<uint64>({ key: 'p' })

  public createApplication(): void {
    this.owner.value = Txn.sender
    this.totalCalls.value = Uint64(0)
    this.totalEarned.value = Uint64(0)
    this.pricePerCall.value = Uint64(5000) // 0.005 ALGO = 5000 microALGOs
  }

  @abimethod()
  public setPrice(newPrice: uint64): void {
    assert(Txn.sender === this.owner.value, 'Only owner can set price')
    this.pricePerCall.value = newPrice
  }

  @abimethod()
  public record_payment(): void {
    // Verify this is part of a group transaction (Payment + App Call)
    assert(Global.groupSize >= Uint64(2), 'Transaction must be part of a group')

    // The payment transaction is expected to be the first in the group
    const payment = gtxn.PaymentTxn(Uint64(0))

    // Verify payment details
    assert(payment.receiver === Global.currentApplicationAddress, 'Payment must be sent to the contract')
    assert(payment.amount >= this.pricePerCall.value, 'Payment amount is below the required price')

    // Update global state
    this.totalCalls.value = this.totalCalls.value + Uint64(1)
    this.totalEarned.value = this.totalEarned.value + payment.amount
  }

  @abimethod()
  public get_stats(): uint64 {
    const calls: uint64 = this.totalCalls.value
    return calls
  }

  @abimethod()
  public withdraw(): void {
    const currentOwner: Account = this.owner.value
    assert(Txn.sender === currentOwner, 'Only owner can withdraw')

    const balance: uint64 = Global.currentApplicationAddress.balance
    const minBalance: uint64 = Global.currentApplicationAddress.minBalance

    // Ensure we leave enough for the Minimum Balance Requirement (MBR)
    assert(balance > minBalance, 'No funds available above MBR')
    const withdrawableAmount: uint64 = balance - minBalance

    itxn.payment({
      receiver: currentOwner,
      amount: withdrawableAmount,
      fee: Uint64(0) // Use fee pooling
    }).submit()
  }
}

